import type { GearItem, WeightUnit } from '@/types/database'

// Type for gear items during parsing - GearItem without database metadata
export type ParsedGearItem = Omit<GearItem, 'id' | 'user_id' | 'created_at' | 'updated_at'>

// CSV row type
export interface CsvRow {
  [key: string]: string
}

export interface ParseResult<T> {
  success: boolean
  data: T[]
  errors: string[]
  warnings: string[]
  metadata?: any
}

export type GearParseResult = ParseResult<ParsedGearItem>

// Common validation functions
export function validateParsedGearItem(item: ParsedGearItem): string[] {
  const errors: string[] = []

  if (!item.description || item.description.length < 2) {
    errors.push('Description must be at least 2 characters')
  }

  if (item.weight_g <= 0) {
    errors.push('Weight must be greater than 0')
  }

  if (item.weight_g > 50000) { // 50kg limit
    errors.push('Weight seems unrealistically high (over 50kg)')
  }

  if (!item.item_type || item.item_type.trim().length === 0) {
    errors.push('Item type is required')
  }

  if (item.price !== null && item.price !== undefined && item.price < 0) {
    errors.push('Price cannot be negative')
  }

  return errors
}

// Helper to convert ParsedGearItem to GearItem creation data
export function toGearItemData(item: ParsedGearItem): Omit<GearItem, 'id' | 'user_id' | 'created_at' | 'updated_at'> {
  return {
    description: item.description,
    item_type: item.item_type,
    brand: item.brand,
    model: item.model,
    consumable: item.consumable,
    price: item.price,
    weight_g: item.weight_g,
    weight_unit_display: item.weight_unit_display,
    notes: item.notes,
    image_url: item.image_url,
    url: item.url
  }
}

// Weight parsing utilities
export interface WeightParseResult {
  grams: number
  unit: WeightUnit
}

export function parseWeightFromText(text: string): WeightParseResult {
  const cleaned = text.toLowerCase().replace(/[^\d.,ozlbkg\s]/g, '').trim()

  // Handle combined lb + oz format (e.g., "1 lb 5 oz")
  if (cleaned.includes('lb') && cleaned.includes('oz')) {
    const lbOzMatch = cleaned.match(/(\d+\.?\d*)\s*lb\s*(\d+\.?\d*)\s*oz/)
    if (lbOzMatch) {
      const lbs = parseFloat(lbOzMatch[1])
      const ozs = parseFloat(lbOzMatch[2])
      const grams = Math.round((lbs * 453.592) + (ozs * 28.3495))
      return { grams, unit: 'oz' } // Display in oz since it has oz precision
    }
  }

  // Single unit parsing
  const patterns = [
    { regex: /(\d+\.?\d*)\s*oz/, unit: 'oz' as WeightUnit, factor: 28.3495 },
    { regex: /(\d+\.?\d*)\s*lb/, unit: 'lb' as WeightUnit, factor: 453.592 },
    { regex: /(\d+\.?\d*)\s*kg/, unit: 'kg' as WeightUnit, factor: 1000 },
    { regex: /(\d+\.?\d*)\s*g/, unit: 'g' as WeightUnit, factor: 1 },
  ]

  for (const pattern of patterns) {
    const match = cleaned.match(pattern.regex)
    if (match) {
      const value = parseFloat(match[1])
      const grams = Math.round(value * pattern.factor)
      return { grams, unit: pattern.unit }
    }
  }

  // Fallback: try to parse as plain number (assume grams)
  const numMatch = cleaned.match(/(\d+\.?\d*)/)
  if (numMatch) {
    const value = parseFloat(numMatch[1])
    return { grams: Math.round(value), unit: 'g' }
  }

  throw new Error(`Could not parse weight from: ${text}`)
}

// Boolean parsing utility
export function parseBoolean(value: string | undefined): boolean {
  if (!value) return false
  const lower = value.toLowerCase().trim()
  return ['true', 'yes', '1', 'on', 'checked', 'x'].includes(lower)
}

// Bulk validation function for arrays of items
export function validateGearItems(items: ParsedGearItem[]): { valid: ParsedGearItem[], invalid: { item: ParsedGearItem, errors: string[] }[] } {
  const valid: ParsedGearItem[] = []
  const invalid: { item: ParsedGearItem, errors: string[] }[] = []

  for (const item of items) {
    const errors = validateParsedGearItem(item)
    if (errors.length === 0) {
      valid.push(item)
    } else {
      invalid.push({ item, errors })
    }
  }

  return { valid, invalid }
}

// Duplicate checking function
export function checkForDuplicates(items: ParsedGearItem[]): { unique: ParsedGearItem[], duplicates: { item: ParsedGearItem, duplicateOf: number }[], warnings: string[] } {
  const unique: ParsedGearItem[] = []
  const duplicates: { item: ParsedGearItem, duplicateOf: number }[] = []

  for (let i = 0; i < items.length; i++) {
    const currentItem = items[i]
    let isDuplicate = false

    for (let j = 0; j < unique.length; j++) {
      const existingItem = unique[j]

      // Check if descriptions match (case-insensitive)
      const descriptionsMatch = currentItem.description.toLowerCase().trim() === existingItem.description.toLowerCase().trim()

      // Check if weights are similar (within 5g)
      const weightsMatch = Math.abs(currentItem.weight_g - existingItem.weight_g) <= 5

      // Check if brands match (case-insensitive, treating null/undefined as empty)
      const brandsMatch = (currentItem.brand || '').toLowerCase().trim() === (existingItem.brand || '').toLowerCase().trim()

      if (descriptionsMatch && weightsMatch && brandsMatch) {
        duplicates.push({ item: currentItem, duplicateOf: j })
        isDuplicate = true
        break
      }
    }

    if (!isDuplicate) {
      unique.push(currentItem)
    }
  }

  const warnings: string[] = []
  if (duplicates.length > 0) {
    warnings.push(`Found ${duplicates.length} potential duplicate${duplicates.length === 1 ? '' : 's'} (similar description/weight/brand)`)
  }

  return { unique, duplicates, warnings }
}

// Common column mapping type
export interface ColumnMap {
  [field: string]: number | undefined
}

import { decode as decodeHtmlEntities } from 'he'
import { 
  type ParsedGearItem, 
  type GearParseResult, 
  validateParsedGearItem 
} from './index'

export function parseLighterPackHtml(html: string): GearParseResult {
  const result: GearParseResult = {
    success: false,
    data: [],
    errors: [],
    warnings: [],
    metadata: {}
  }

  try {
    // Extract list name from title or h1
    const titleMatch = html.match(/<title[^>]*>([^<]+)<\/title>/i) || 
                      html.match(/<h1[^>]*>([^<]+)<\/h1>/i)

    if (titleMatch) {
      result.metadata.listName = titleMatch[1].replace(/\s*-\s*LighterPack.*$/i, '').trim()
    }

    // Look for all lpItem elements across all categories
    const itemMatches = html.match(/<li[^>]*class="[^"]*lpItem[^"]*"[^>]*>.*?<\/li>/gis)


    if (!itemMatches || itemMatches.length === 0) {
      result.errors.push('No gear items found in the LighterPack page')
      return result
    }

    // Parse each item
    for (const itemHtml of itemMatches) {
      try {
        const item = parseHtmlItem(itemHtml)
        if (item) {
          const validationErrors = validateParsedGearItem(item)
          if (validationErrors.length === 0) {
            result.data.push(item)
          } else {
            result.errors.push(`Invalid item: ${validationErrors.join(', ')}`)
          }
        }
      } catch (error) {
        const message = error instanceof Error ? error.message : 'Unknown error'
        result.warnings.push(`Failed to parse item: ${message}`)
      }
    }

    // Calculate metadata
    if (result.data.length > 0) {
      result.metadata.totalWeight = result.data.reduce((sum, item) => sum + item.weight_g, 0)
      result.metadata.itemCount = result.data.length
    }

    result.success = result.data.length > 0

    if (result.data.length === 0) {
      result.errors.push('No gear items found in the LighterPack page')
    }

    return result

  } catch (error) {
    result.errors.push(error instanceof Error ? error.message : 'Unknown parsing error')
    return result
  }
}

function parseHtmlItem(itemHtml: string): ParsedGearItem | null {
  try {
    // Extract name (item_type) from lpName span - handle both plain text and anchor tags
    const nameSpanMatch = itemHtml.match(/<span[^>]*class="[^"]*lpName[^"]*"[^>]*>(.*?)<\/span>/is)
    let name = null
    if (nameSpanMatch) {
      // Check if there's an anchor tag inside
      const anchorMatch = nameSpanMatch[1].match(/<a[^>]*>([^<]+)<\/a>/i)
      name = anchorMatch ? anchorMatch[1].trim() : nameSpanMatch[1].trim()
    }

    if (!name) {
      return null
    }

    // Extract description from lpDesc span, or anchor text within lpName
    let description = name // fallback to name

    // Try to get description from lpDescription
    const descMatch = itemHtml.match(/<span[^>]*class="[^"]*lpDescription[^"]*"[^>]*>([^<]+)<\/span>/i)
    if (descMatch?.[1]?.trim()) {
      description = descMatch[1].trim()
    } else {
      // Try to get from anchor text in lpName
      const anchorMatch = itemHtml.match(/<a[^>]*>([^<]+)<\/a>/i)
      if (anchorMatch?.[1]?.trim() && anchorMatch[1].trim() !== name) {
        description = anchorMatch[1].trim()
      }
    }

    // Extract URL from anchor in lpName
    const urlMatch = itemHtml.match(/<a[^>]*href="([^"]+)"/i)
    const url = urlMatch?.[1] ? decodeHtmlEntities(urlMatch[1]) : null

    // Extract weight and unit from lpWeight span and lpUnitSelect
    const weightMatch = itemHtml.match(/<span[^>]*class="[^"]*lpWeight[^"]*"[^>]*>([^<]+)<\/span>/i)
    if (!weightMatch) return null

    const unitMatch = itemHtml.match(/<span[^>]*class="[^"]*lpDisplay[^"]*"[^>]*>([^<]+)<\/span>/i)
    const unit = unitMatch?.[1]?.trim() || 'g'

    const weight = parseFloat(weightMatch[1])
    if (isNaN(weight)) return null

    // Convert to grams based on unit
    let weight_g: number
    switch (unit.toLowerCase()) {
      case 'oz':
        weight_g = Math.round(weight * 28.3495)
        break
      case 'lb':
        weight_g = Math.round(weight * 453.592)
        break
      case 'kg':
        weight_g = Math.round(weight * 1000)
        break
      case 'g':
      default:
        weight_g = Math.round(weight)
        break
    }

    const weight_unit_display = unit as 'g' | 'oz' | 'lb' | 'kg'


    // Check if item is consumable (must have an i element with both lpConsumable and lpActive classes)
    const consumable = /<i[^>]*class="[^"]*lpConsumable[^"]*lpActive[^"]*"[^>]*>|<i[^>]*class="[^"]*lpActive[^"]*lpConsumable[^"]*"[^>]*>/i.test(itemHtml)

    // Extract price from lpPriceCell span
    const priceMatch = itemHtml.match(/<span[^>]*class="[^"]*lpPriceCell[^"]*"[^>]*>\$?([0-9.,]+)<\/span>/i)
    const price = priceMatch ? parseFloat(priceMatch[1].replace(/[,$]/g, '')) : null

    // Use name directly as item_type (preserve original data)
    const item_type = name

    const result = {
      description: description || name, // Use description as the main field, fallback to name
      brand: null, // LighterPack doesn't separate brand info
      model: null,
      weight_g,
      weight_unit_display,
      item_type,
      consumable,
      price,
      notes: null, // LighterPack doesn't have separate notes
      image_url: null,
      url
    }

    return result

  } catch (error) {
    console.warn('Error parsing LighterPack item:', error)
    return null
  }
}

export async function parseLighterPackUrl(url: string): Promise<GearParseResult> {
  const result: GearParseResult = {
    success: false,
    data: [],
    errors: [],
    warnings: []
  }

  // Validate URL format
  if (!url.match(/^https:\/\/lighterpack\.com\/r\/[a-zA-Z0-9]+$/)) {
    result.errors.push('Invalid LighterPack URL format. Expected: https://lighterpack.com/r/[ID]')
    return result
  }

  // For now, direct URL import is not implemented
  result.errors.push('Direct URL import not yet implemented. Please use CSV export from LighterPack for now.')
  return result
}

import { describe, it, expect } from 'vitest'
import { readFileSync } from 'fs'
import { join } from 'path'
import { parseCsv } from './csv'
import { validateGearItems, checkForDuplicates } from './index'

describe('CSV Parser - Real LighterPack Examples', () => {
  const examplesPath = join(process.cwd(), 'tests/examples/lighterpack/csv')

  describe('Trail Running CSV', () => {
    it('should parse trail-running.csv correctly', () => {
      const csvContent = readFileSync(join(examplesPath, 'trail-running.csv'), 'utf-8')
      const result = parseCsv(csvContent)

      expect(result.success).toBe(true)
      expect(result.errors).toHaveLength(0)
      expect(result.data.length).toBeGreaterThan(0)

      // Check specific items
      const hydrationVest = result.data.find(item => item.description === 'Hydration Vest')
      expect(hydrationVest).toBeDefined()
      expect(hydrationVest?.weight_g).toBe(250)
      expect(hydrationVest?.item_type).toBe('🎒 Pack')
      // Brand detection removed - parser preserves original data
      expect(hydrationVest?.brand).toBe(null)
      expect(hydrationVest?.notes).toBeDefined()

      const hikingPoles = result.data.find(item => item.description === 'Hiking Poles')
      expect(hikingPoles).toBeDefined()
      expect(hikingPoles?.weight_g).toBe(275)
      // Brand detection removed - parser preserves original data
      expect(hikingPoles?.brand).toBe(null)
    })

    it('should validate all items from trail-running.csv', () => {
      const csvContent = readFileSync(join(examplesPath, 'trail-running.csv'), 'utf-8')
      const result = parseCsv(csvContent)
      const validation = validateGearItems(result.data)

      expect(validation.invalid).toHaveLength(0)
      expect(validation.valid.length).toBe(result.data.length)
    })
  })

  describe('Four Pass Loop CSV', () => {
    it('should parse four-pass-loop.csv correctly', () => {
      const csvContent = readFileSync(join(examplesPath, 'four-pass-loop.csv'), 'utf-8')
      const result = parseCsv(csvContent)

      expect(result.success).toBe(true)
      expect(result.errors).toHaveLength(0)
      expect(result.data.length).toBeGreaterThan(20)

      // Check category diversity
      const categories = new Set(result.data.map(item => item.item_type))
      expect(categories.size).toBeGreaterThan(5)

      // Check specific item with URL and price
      const backpack = result.data.find(item => item.description === 'Backpack')
      expect(backpack).toBeDefined()
      expect(backpack?.weight_g).toBe(1960)
      expect(backpack?.price).toBe(315)
      // Brand detection removed - parser preserves original data
      expect(backpack?.brand).toBe(null)

      // Check sleeping system items
      const sleepingBag = result.data.find(item => item.description === 'Sleeping Bag')
      expect(sleepingBag).toBeDefined()
      expect(sleepingBag?.item_type).toBe('🛌 Sleep System')
      expect(sleepingBag?.weight_g).toBe(500)
    })

    it('should handle duplicates in four-pass-loop.csv', () => {
      const csvContent = readFileSync(join(examplesPath, 'four-pass-loop.csv'), 'utf-8')
      const result = parseCsv(csvContent)
      const duplicateCheck = checkForDuplicates(result.data)

      // Check that similar items (like multiple socks) are not marked as duplicates
      expect(duplicateCheck.unique.length).toBeGreaterThan(0)

      // Categories should be preserved
      const categories = new Set(duplicateCheck.unique.map(item => item.item_type))
      expect(categories).toContain('🎒 Pack')
      expect(categories).toContain('🛌 Sleep System')
      expect(categories).toContain('💧 Hydration')
    })
  })

  describe('JMT Loadout CSV', () => {
    it('should parse jmt-loadout.csv correctly', () => {
      const csvContent = readFileSync(join(examplesPath, 'jmt-loadout.csv'), 'utf-8')
      const result = parseCsv(csvContent)

      expect(result.success).toBe(true)
      expect(result.errors).toHaveLength(0)
      expect(result.data.length).toBeGreaterThan(30)

      // Check multiple quantity items
      const buff = result.data.find(item => item.description === 'Buff')
      expect(buff).toBeDefined()

      // Check brand extraction from desc field
      const campShirt = result.data.find(item => item.description === 'Camp Shirt')
      expect(campShirt).toBeDefined()
      // Brand detection removed - parser preserves original data
      expect(campShirt?.brand).toBe(null)
      expect(campShirt?.notes).toBeDefined()

      // Check item with comma in label
      const spareSocks = result.data.find(item => item.description?.includes('Hiking Socks, Spare'))
      expect(spareSocks).toBeDefined()
    })

    it('should extract all brands from jmt-loadout.csv', () => {
      const csvContent = readFileSync(join(examplesPath, 'jmt-loadout.csv'), 'utf-8')
      const result = parseCsv(csvContent)

      // Brand detection removed - parser preserves original data
      const itemsWithBrands = result.data.filter(item => item.brand)
      expect(itemsWithBrands.length).toBe(0) // No automatic brand detection
      // No brand assertions since we don't do automatic detection
    })

    it('should handle consumable flags in jmt-loadout.csv', () => {
      const csvContent = readFileSync(join(examplesPath, 'jmt-loadout.csv'), 'utf-8')
      const result = parseCsv(csvContent)

      // Check consumable items
      const consumableItems = result.data.filter(item => item.consumable)

      // Most items should not be consumable in a gear list
      expect(consumableItems.length).toBeLessThan(result.data.length / 2)
    })
  })

  describe('Cross-file analysis', () => {
    it('should handle all three CSV files without errors', () => {
      const files = ['trail-running.csv', 'four-pass-loop.csv', 'jmt-loadout.csv']

      files.forEach(filename => {
        const csvContent = readFileSync(join(examplesPath, filename), 'utf-8')
        const result = parseCsv(csvContent)

        expect(result.success).toBe(true)
        expect(result.data.length).toBeGreaterThan(0)

        // All items should have required fields
        result.data.forEach(item => {
          expect(item.description).toBeTruthy()
          expect(item.weight_g).toBeGreaterThan(0)
          expect(item.item_type).toBeTruthy()
          expect(typeof item.consumable).toBe('boolean')
        })
      })
    })

    it('should preserve emoji categories from all files', () => {
      const files = ['trail-running.csv', 'four-pass-loop.csv', 'jmt-loadout.csv']
      const allCategories = new Set<string>()

      files.forEach(filename => {
        const csvContent = readFileSync(join(examplesPath, filename), 'utf-8')
        const result = parseCsv(csvContent)
        result.data.forEach(item => allCategories.add(item.item_type))
      })

      // Should preserve emoji categories
      expect(Array.from(allCategories).some(cat => cat.includes('🎒'))).toBe(true)
      expect(Array.from(allCategories).some(cat => cat.includes('🥋'))).toBe(true)
      expect(Array.from(allCategories).some(cat => cat.includes('💧'))).toBe(true)
    })
  })
})

