export function validateParsedList(list: ParsedList): string[] {
  const errors: string[] = []

  if (!list.name || list.name.trim().length < 1) {
    errors.push('List name is required')
  }

  if (list.name && list.name.length > 100) {
    errors.push('List name must be less than 100 characters')
  }

  return errors
}

export function validateParsedListCategory(category: ParsedListCategory): string[] {
  const errors: string[] = []

  if (!category.name || category.name.trim().length < 1) {
    errors.push('Category name is required')
  }

  if (category.name && category.name.length > 50) {
    errors.push('Category name must be less than 50 characters')
  }

  if (category.sort_index < 0) {
    errors.push('Category sort index must be non-negative')
  }

  return errors
}

export function validateParsedListedGearItem(item: ParsedListedGearItem): string[] {
  const errors: string[] = []

  if (item.quantity <= 0) {
    errors.push('Quantity must be greater than 0')
  }

  if (item.quantity > 100) {
    errors.push('Quantity seems unrealistically high (over 100)')
  }

  if (item.weight_g_override !== null && item.weight_g_override !== undefined) {
    if (item.weight_g_override <= 0) {
      errors.push('Weight override must be greater than 0')
    }
    if (item.weight_g_override > 50000) {
      errors.push('Weight override seems unrealistically high (over 50kg)')
    }
  }

  if (!item.categoryName || item.categoryName.trim().length === 0) {
    errors.push('Category name is required')
  }

  // Validate the gear item
  const gearErrors = validateParsedGearItem(item.gearItem)
  errors.push(...gearErrors.map(err => `Gear item: ${err}`))

  return errors
}

