import { useState, useEffect } from 'react'
import { useAuth } from '@/contexts/AuthContext'
import { createGearRepository } from '@/lib/gearRepository'
import { Button } from '@/components/ui/button'
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card'
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs'
import { Upload, Link } from 'lucide-react'
import { CsvImport } from './CsvImport'
import { UrlImport } from './UrlImport'
import { ImportPreview } from './ImportPreview'
import type { ParsedGearItem, ListParseResult } from '@/utils/parser'
import type { GearItem } from '@/types/database'

interface ImportGearFormProps {
  onCancel?: () => void
  className?: string
}

export interface ImportState {
  step: 'input' | 'preview'
  mode: 'gear' | 'list' // New: track import mode
  // Legacy gear import fields
  items: ParsedGearItem[]
  newItems: ParsedGearItem[]
  duplicates: ParsedGearItem[]
  errors: string[]
  warnings: string[]
  metadata?: {
    listName?: string
    totalWeight?: number
    itemCount?: number
  }
  // New list import fields
  listResult?: ListParseResult
}

export function ImportGearForm({ onCancel, className }: ImportGearFormProps) {
  const { user } = useAuth()
  const [activeTab, setActiveTab] = useState<'csv' | 'url'>('url')
  const [existingItems, setExistingItems] = useState<GearItem[]>([])
  const [importState, setImportState] = useState<ImportState>({
    step: 'input',
    mode: 'gear', // Default to gear mode for backward compatibility
    items: [],
    newItems: [],
    duplicates: [],
    errors: [],
    warnings: [],
    listResult: undefined
  })

  // Fetch existing gear items on mount
  useEffect(() => {
    const fetchExistingItems = async () => {
      if (!user) return

      try {
        const gearRepository = createGearRepository(user.id)
        const items = await gearRepository.list()
        setExistingItems(items)
      } catch (error) {
        console.error('Failed to fetch existing gear items:', error)
      }
    }

    fetchExistingItems()
  }, [user])

  // Function to check if two items are duplicates
  const isDuplicate = (importItem: ParsedGearItem, existingItem: GearItem): boolean => {
    // Match on item_type and description (case insensitive)
    const importItemType = importItem.item_type.toLowerCase().trim()
    const importDescription = (importItem.description || '').toLowerCase().trim()
    const existingItemType = existingItem.item_type.toLowerCase().trim()
    const existingDescription = (existingItem.description || '').toLowerCase().trim()

    return importItemType === existingItemType && importDescription === existingDescription
  }

  const handleImportData = (data: ParsedGearItem[], errors: string[] = [], warnings: string[] = [], metadata?: any) => {
    // Deduplicate against existing items
    const newItems: ParsedGearItem[] = []
    const duplicates: ParsedGearItem[] = []

    data.forEach(importItem => {
      const isDuplicateItem = existingItems.some(existing => isDuplicate(importItem, existing))
      if (isDuplicateItem) {
        duplicates.push(importItem)
      } else {
        newItems.push(importItem)
      }
    })

    // Add deduplication warnings (summary only, no ugly lists)
    const updatedWarnings = [...warnings]
    if (duplicates.length > 0) {
      updatedWarnings.push(
        `${duplicates.length} items skipped as duplicates (already exist in your gear library)`
      )
    }

    if (newItems.length > 0) {
      updatedWarnings.push(`${newItems.length} new items ready to import`)
    }

    setImportState({
      step: 'preview', // Always show preview, even if no new items
      mode: 'gear',
      items: data,
      newItems,
      duplicates,
      errors,
      warnings: updatedWarnings,
      metadata,
      listResult: undefined
    })
  }

  // New handler for list imports
  const handleListImportData = (listResult: ListParseResult) => {
    setImportState({
      step: 'preview',
      mode: 'list',
      items: [], // Not used in list mode
      newItems: [], // Not used in list mode
      duplicates: [], // Not used in list mode
      errors: listResult.errors,
      warnings: listResult.warnings,
      metadata: listResult.metadata,
      listResult
    })
  }


  const handleReset = () => {
    setImportState({
      step: 'input',
      mode: 'gear',
      items: [],
      newItems: [],
      duplicates: [],
      errors: [],
      warnings: [],
      metadata: undefined,
      listResult: undefined
    })
  }

  const handleClose = () => {
    handleReset()
    onCancel?.()
  }

  if (importState.step === 'preview') {
    return (
      <ImportPreview
        mode={importState.mode}
        newItems={importState.newItems}
        duplicates={importState.duplicates}
        errors={importState.errors}
        warnings={importState.warnings}
        metadata={importState.metadata}
        listResult={importState.listResult}
        onCancel={handleReset}
        className={className}
      />
    )
  }


  return (
    <Card className={className}>
      <CardHeader className="pb-3">
        <CardTitle className="text-lg">Import Gear</CardTitle>
        <CardDescription className="text-sm">
          Import your gear from LighterPack by URL or CSV file
        </CardDescription>
      </CardHeader>
      <CardContent>
        <Tabs defaultValue="url" value={activeTab} onValueChange={(value) => setActiveTab(value as 'csv' | 'url')}>
          <TabsList className="grid w-full grid-cols-2">
            <TabsTrigger value="url" className="flex items-center gap-2">
              <Link className="h-4 w-4" />
              LighterPack URL
            </TabsTrigger>
            <TabsTrigger value="csv" className="flex items-center gap-2">
              <Upload className="h-4 w-4" />
              CSV File
            </TabsTrigger>
          </TabsList>

          <TabsContent value="url" className="mt-4">
            <UrlImport onImportData={handleImportData} />
          </TabsContent>

          <TabsContent value="csv" className="mt-4">
            <CsvImport onImportData={handleImportData} />
          </TabsContent>
        </Tabs>

        <div className="flex justify-end gap-2 mt-4 pt-3 border-t">
          <Button variant="ghost" onClick={handleClose} size="sm">
            Cancel
          </Button>
        </div>
      </CardContent>
    </Card>
  )
}

import { useState, useRef } from 'react'
import { Button } from '@/components/ui/button'
import { Alert, AlertDescription } from '@/components/ui/alert'
import { Upload, FileText, Info } from 'lucide-react'
import { parseCsv } from '@/utils/parser/csv'
import { validateGearItems, checkForDuplicates } from '@/utils/parser'
import type { ParsedGearItem } from '@/utils/parser'

interface CsvImportProps {
  onImportData: (items: ParsedGearItem[], errors?: string[], warnings?: string[]) => void
}

export function CsvImport({ onImportData }: CsvImportProps) {
  const [isDragOver, setIsDragOver] = useState(false)
  const [isProcessing, setIsProcessing] = useState(false)
  const [fileName, setFileName] = useState<string | null>(null)
  const fileInputRef = useRef<HTMLInputElement>(null)

  const handleFileSelect = (file: File) => {
    if (!file.name.toLowerCase().endsWith('.csv')) {
      onImportData([], ['Please select a CSV file (.csv extension)'])
      return
    }

    setFileName(file.name)
    setIsProcessing(true)

    const reader = new FileReader()
    reader.onload = (e) => {
      const csvContent = e.target?.result as string
      processCsvContent(csvContent)
    }
    reader.onerror = () => {
      onImportData([], ['Failed to read file. Please try again.'])
      setIsProcessing(false)
    }
    reader.readAsText(file)
  }

  const processCsvContent = (csvContent: string) => {
    try {
      // Parse CSV
      const parseResult = parseCsv(csvContent)

      if (!parseResult.success) {
        onImportData([], parseResult.errors, parseResult.warnings)
        setIsProcessing(false)
        return
      }

      // Validate items
      const { valid, invalid } = validateGearItems(parseResult.data)

      const errors: string[] = [...parseResult.errors]
      const warnings: string[] = [...parseResult.warnings]

      // Add validation errors
      invalid.forEach(({ item, errors: itemErrors }) => {
        errors.push(`"${item.description}": ${itemErrors.join(', ')}`)
      })

      // Add warnings for any issues
      if (invalid.length > 0) {
        warnings.push(`${invalid.length} items had validation errors and were skipped`)
      }

      // Check for duplicates in valid items
      const { unique, duplicates, warnings: duplicateWarnings } = checkForDuplicates(valid)
      warnings.push(...duplicateWarnings)

      if (duplicates.length > 0) {
        duplicates.forEach(({ item }) => {
          warnings.push(`Removed duplicate: "${item.name}" (${item.weight_grams}g)`)
        })
      }

      if (unique.length > 0) {
        warnings.push(`Successfully parsed ${unique.length} unique items`)
      }

      onImportData(unique, errors, warnings)

    } catch (error) {
      onImportData([], [`Unexpected error: ${error instanceof Error ? error.message : 'Unknown error'}`])
    } finally {
      setIsProcessing(false)
    }
  }

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault()
    setIsDragOver(true)
  }

  const handleDragLeave = (e: React.DragEvent) => {
    e.preventDefault()
    setIsDragOver(false)
  }

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault()
    setIsDragOver(false)

    const files = Array.from(e.dataTransfer.files)
    if (files.length > 0) {
      handleFileSelect(files[0])
    }
  }

  const handleFileInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files
    if (files && files.length > 0) {
      handleFileSelect(files[0])
    }
  }

  const handleClickUpload = () => {
    fileInputRef.current?.click()
  }

  return (
    <div className="space-y-4">
      {/* Instructions */}
      <Alert>
        <Info className="h-4 w-4" />
        <AlertDescription>
          <div className="font-medium mb-2">How to export from LighterPack:</div>
          <ol className="list-decimal list-inside space-y-1 text-sm">
            <li>Go to your LighterPack list</li>
            <li>Click the "Export" button</li>
            <li>Select "CSV" format</li>
            <li>Upload the downloaded file below</li>
          </ol>
        </AlertDescription>
      </Alert>

      {/* File Upload Area */}
      <div
        className={`
          border-2 border-dashed rounded-lg p-8 text-center transition-colors
          ${isDragOver ? 'border-primary bg-primary/5' : 'border-muted-foreground/25'}
          ${isProcessing ? 'opacity-50 pointer-events-none' : 'cursor-pointer hover:border-primary hover:bg-primary/5'}
        `}
        onDragOver={handleDragOver}
        onDragLeave={handleDragLeave}
        onDrop={handleDrop}
        onClick={handleClickUpload}
      >
        <input
          ref={fileInputRef}
          type="file"
          accept=".csv"
          onChange={handleFileInputChange}
          className="hidden"
          disabled={isProcessing}
        />

        <div className="space-y-3">
          {isProcessing ? (
            <>
              <div className="animate-spin rounded-full h-10 w-10 border-b-2 border-primary mx-auto" />
              <div className="text-sm font-medium">Processing {fileName}...</div>
            </>
          ) : (
            <>
              <Upload className="h-10 w-10 text-muted-foreground mx-auto" />
              <div>
                <div className="font-medium">Drop your CSV file here</div>
                <div className="text-sm text-muted-foreground mt-1">
                  or click to browse files
                </div>
              </div>
              <div className="text-xs text-muted-foreground">
                Supports LighterPack CSV exports (.csv files up to 10MB)
              </div>
            </>
          )}
        </div>
      </div>

      {/* Manual Upload Button */}
      <div className="text-center">
        <Button
          variant="outline"
          onClick={handleClickUpload}
          disabled={isProcessing}
          className="w-full sm:w-auto"
        >
          <FileText className="h-4 w-4 mr-2" />
          Choose CSV File
        </Button>
      </div>

      {/* CSV Format Info */}
      <Alert>
        <Info className="h-4 w-4" />
        <AlertDescription>
          <div className="font-medium mb-2">Expected CSV format:</div>
          <div className="text-sm space-y-1">
            <div><strong>Required columns:</strong> Name, Weight</div>
            <div><strong>Optional columns:</strong> Brand, Category, Quantity, Worn, Consumable, Price, Description, Notes</div>
            <div className="text-muted-foreground">Column names are flexible - we'll automatically detect common variations.</div>
          </div>
        </AlertDescription>
      </Alert>
    </div>
  )
}

