import { Info, ExternalLink, List, Package } from 'lucide-react'
import { parseLighterPackHtml, parseLighterPackHtmlToList } from '@/utils/parser/lighterpack'
import type { ParsedGearItem, ListParseResult } from '@/utils/parser'

interface UrlImportProps {
  onImportData: (items: ParsedGearItem[], errors?: string[], warnings?: string[], metadata?: any) => void
  onListImportData: (listResult: ListParseResult) => void
}

export function UrlImport({ onImportData, onListImportData }: UrlImportProps) {
  const [url, setUrl] = useState('')
  const [isProcessing, setIsProcessing] = useState(false)

  const handleUrlImport = async () => {
    if (!url.trim()) {
      const errorResult: ListParseResult = {
        success: false,
        list: { name: 'Failed Import' },
        categories: [],
        listedGearItems: [],
        errors: ['Please enter a LighterPack URL'],
        warnings: [],
        metadata: {}
      }
      onListImportData(errorResult)
      return
    }

    // Validate URL format
    if (!url.includes('lighterpack.com/r/')) {
      const errorResult: ListParseResult = {
        success: false,
        list: { name: 'Failed Import' },
        categories: [],
        listedGearItems: [],
        errors: ['Invalid URL. Please enter a valid LighterPack share URL (e.g., https://lighterpack.com/r/abc123)'],
        warnings: [],
        metadata: {}
      }
      onListImportData(errorResult)
      return
    }

    setIsProcessing(true)

    try {
      // Use CORS proxy to fetch the LighterPack page
      // Try multiple CORS proxies for better reliability
      const proxies = [
        `https://api.allorigins.win/get?url=${encodeURIComponent(url.trim())}`,
        `https://corsproxy.io/?${encodeURIComponent(url.trim())}`,
        `https://cors-anywhere.herokuapp.com/${url.trim()}`
      ]

      let html = null
      let lastError = null

      for (const proxyUrl of proxies) {
        try {
            const response = await fetch(proxyUrl, {
            headers: {
              'X-Requested-With': 'XMLHttpRequest'
            }
          })

          if (!response.ok) {
            throw new Error(`HTTP ${response.status}: ${response.statusText}`)
          }

          if (proxyUrl.includes('allorigins.win')) {
            const data = await response.json()
            if (!data.contents) {
              throw new Error('No content received from allorigins proxy')
            }
            html = data.contents
          } else {
            html = await response.text()
          }

          if (html && html.includes('lighterpack')) {
            break
          } else {
            throw new Error('Invalid LighterPack content received')
          }
        } catch (error) {
          lastError = error
          continue
        }
      }

      if (!html) {
        throw new Error(`All CORS proxies failed. Last error: ${lastError instanceof Error ? lastError.message : 'Unknown error'}`)
      }

      // Parse the HTML content based on import mode
      if (importMode === 'list') {
        // Parse as complete list structure
        const listResult = parseLighterPackHtmlToList(html)
        onListImportData(listResult)
      } else {
        // Legacy gear-only parsing
        const result = parseLighterPackHtml(html)

        if (result.success) {
          const successMessage = result.metadata?.listName
            ? [`Successfully parsed "${result.metadata.listName}"`]
            : []
          onImportData(result.data, result.errors, successMessage, result.metadata)
        } else {
          onImportData([], result.errors)
        }
      }
    } catch (error) {
      const errorMessage = `Failed to import from URL: ${error instanceof Error ? error.message : 'Unknown error'}`
      if (importMode === 'list') {
        // Create an error result for list import
        const errorResult: ListParseResult = {
          success: false,
          list: { name: 'Failed Import' },
          categories: [],
          listedGearItems: [],
          errors: [errorMessage],
          warnings: [],
          metadata: {}
        }
        onListImportData(errorResult)
      } else {
        onImportData([], [errorMessage])
      }
    } finally {
      setIsProcessing(false)
    }
  }

  return (
    <div className="space-y-4">
      {/* Import Mode Selection */}
      <div className="bg-muted/30 rounded-lg p-4 space-y-3">
        <div className="font-medium text-sm">Import Mode</div>
        <div className="grid grid-cols-2 gap-2">
          <Button
            variant={importMode === 'list' ? 'default' : 'outline'}
            onClick={() => setImportMode('list')}
            className="justify-start h-auto p-3"
            disabled={isProcessing}
          >
            <List className="h-4 w-4 mr-2 flex-shrink-0" />
            <div className="text-left">
              <div className="font-medium">Import as List</div>
              <div className="text-xs opacity-75">
                Creates list with categories
              </div>
            </div>
          </Button>
          <Button
            variant={importMode === 'gear' ? 'default' : 'outline'}
            onClick={() => setImportMode('gear')}
            className="justify-start h-auto p-3"
            disabled={isProcessing}
          >
            <Package className="h-4 w-4 mr-2 flex-shrink-0" />
            <div className="text-left">
              <div className="font-medium">Import as Gear</div>
              <div className="text-xs opacity-75">
                Adds items to gear library
              </div>
            </div>
          </Button>
        </div>
      </div>

      {/* URL Input */}
      <div className="space-y-2">
        <div className="flex items-center justify-between">
          <Label htmlFor="lighterpack-url">LighterPack URL</Label>
          <Button
            variant="ghost"
            size="sm"
            onClick={() => window.open('https://lighterpack.com/r/q7l72y', '_blank')}
          >
            <ExternalLink className="h-3 w-3 mr-1" />
            View Example
          </Button>
        </div>
        <div className="flex gap-2">
          <Input
            id="lighterpack-url"
            type="url"
            placeholder="https://lighterpack.com/r/q7l72y"
            value={url}
            onChange={(e) => setUrl(e.target.value)}
            disabled={isProcessing}
            className="flex-1"
          />
          <Button
            onClick={handleUrlImport}
            disabled={!url.trim() || isProcessing}
          >
            {isProcessing ? (
              <>
                <div className="animate-spin rounded-full h-4 w-4 border-b-2 border-current mr-2" />
                Loading...
              </>
            ) : (
              'Import'
            )}
          </Button>
        </div>
        <div className="text-sm text-muted-foreground">
          Enter the share URL from your LighterPack list
        </div>
      </div>

      {/* Instructions */}
      <Alert>
        <Info className="h-4 w-4" />
        <AlertDescription>
          <div className="font-medium mb-2">How to get your LighterPack URL:</div>
          <ol className="list-decimal list-inside space-y-1 text-sm">
            <li>Go to your LighterPack list</li>
            <li>Hover over the "Share" link and copy the list URL</li>
            <li>It should look like: <code className="bg-muted px-1 rounded">lighterpack.com/r/abc123</code></li>
            <li>Copy and paste the entire URL above</li>
          </ol>
        </AlertDescription>
      </Alert>

      {/* What Gets Imported */}
      <Alert>
        <Info className="h-4 w-4" />
        <AlertDescription>
          <div className="font-medium mb-2">What gets imported:</div>
          {importMode === 'list' ? (
            <ul className="list-disc list-inside space-y-1 text-sm">
              <li>Complete list structure with categories and organization</li>
              <li>All gear items with quantities and worn status</li>
              <li>Weights, brands, prices, URLs, and notes</li>
              <li>Existing gear items are reused, new ones created as needed</li>
            </ul>
          ) : (
            <ul className="list-disc list-inside space-y-1 text-sm">
              <li>All gear items with item types and descriptions</li>
              <li>Weights (preserved in original units - oz, lb, kg, or g)</li>
              <li>Brands, prices, URLs, notes, and consumable flags</li>
              <li>Duplicates are automatically detected and skipped</li>
            </ul>
          )}
        </AlertDescription>
      </Alert>
    </div>
  )
}

