import { useState, useEffect } from 'react'
import { useAuth } from '@/contexts/AuthContext'
import { createGearRepository } from '@/lib/gearRepository'
import { Button } from '@/components/ui/button'
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card'
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs'
import { Upload, Link } from 'lucide-react'
import { CsvImport } from './CsvImport'
import { UrlImport } from './UrlImport'
import { ImportPreview } from './ImportPreview'
import type { ParsedGearItem, ListParseResult } from '@/utils/parser'
import type { GearItem } from '@/types/database'

interface ImportGearFormProps {
  onCancel?: () => void
  className?: string
}

export interface ImportState {
  step: 'input' | 'preview'
  mode: 'gear' | 'list' // New: track import mode
  // Legacy gear import fields
  items: ParsedGearItem[]
  newItems: ParsedGearItem[]
  duplicates: ParsedGearItem[]
  errors: string[]
  warnings: string[]
  metadata?: {
    listName?: string
    totalWeight?: number
    itemCount?: number
  }
  // New list import fields
  listResult?: ListParseResult
}

export function ImportGearForm({ onCancel, className }: ImportGearFormProps) {
  const { user } = useAuth()
  const [activeTab, setActiveTab] = useState<'csv' | 'url'>('url')
  const [existingItems, setExistingItems] = useState<GearItem[]>([])
  const [importState, setImportState] = useState<ImportState>({
    step: 'input',
    mode: 'gear', // Default to gear mode for backward compatibility
    items: [],
    newItems: [],
    duplicates: [],
    errors: [],
    warnings: [],
    listResult: undefined
  })

  // Fetch existing gear items on mount
  useEffect(() => {
    const fetchExistingItems = async () => {
      if (!user) return

      try {
        const gearRepository = createGearRepository(user.id)
        const items = await gearRepository.list()
        setExistingItems(items)
      } catch (error) {
        console.error('Failed to fetch existing gear items:', error)
      }
    }

    fetchExistingItems()
  }, [user])

  // Function to check if two items are duplicates
  const isDuplicate = (importItem: ParsedGearItem, existingItem: GearItem): boolean => {
    // Match on item_type and description (case insensitive)
    const importItemType = importItem.item_type.toLowerCase().trim()
    const importDescription = (importItem.description || '').toLowerCase().trim()
    const existingItemType = existingItem.item_type.toLowerCase().trim()
    const existingDescription = (existingItem.description || '').toLowerCase().trim()

    return importItemType === existingItemType && importDescription === existingDescription
  }

  const handleImportData = (data: ParsedGearItem[], errors: string[] = [], warnings: string[] = [], metadata?: any) => {
    // Deduplicate against existing items
    const newItems: ParsedGearItem[] = []
    const duplicates: ParsedGearItem[] = []

    data.forEach(importItem => {
      const isDuplicateItem = existingItems.some(existing => isDuplicate(importItem, existing))
      if (isDuplicateItem) {
        duplicates.push(importItem)
      } else {
        newItems.push(importItem)
      }
    })

    // Add deduplication warnings (summary only, no ugly lists)
    const updatedWarnings = [...warnings]
    if (duplicates.length > 0) {
      updatedWarnings.push(
        `${duplicates.length} items skipped as duplicates (already exist in your gear library)`
      )
    }

    if (newItems.length > 0) {
      updatedWarnings.push(`${newItems.length} new items ready to import`)
    }

    setImportState({
      step: 'preview', // Always show preview, even if no new items
      mode: 'gear',
      items: data,
      newItems,
      duplicates,
      errors,
      warnings: updatedWarnings,
      metadata,
      listResult: undefined
    })
  }

  // New handler for list imports
  const handleListImportData = (listResult: ListParseResult) => {
    // For list imports, we don't do gear-level duplicate checking
    // The import service will handle reusing existing gear items
    // but we still create the complete list structure

    setImportState({
      step: 'preview',
      mode: 'list',
      items: [], // Not used in list mode
      newItems: [], // Not used in list mode - all items are shown in the list
      duplicates: [], // Not used in list mode - duplicates are handled at import time
      errors: listResult.errors,
      warnings: listResult.warnings,
      metadata: listResult.metadata,
      listResult
    })
  }


  const handleReset = () => {
    setImportState({
      step: 'input',
      mode: 'gear',
      items: [],
      newItems: [],
      duplicates: [],
      errors: [],
      warnings: [],
      metadata: undefined,
      listResult: undefined
    })
  }

  const handleClose = () => {
    handleReset()
    onCancel?.()
  }

  if (importState.step === 'preview') {
    return (
      <ImportPreview
        mode={importState.mode}
        newItems={importState.newItems}
        duplicates={importState.duplicates}
        errors={importState.errors}
        warnings={importState.warnings}
        metadata={importState.metadata}
        listResult={importState.listResult}
        onCancel={handleReset}
        className={className}
      />
    )
  }


  return (
    <Card className={className}>
      <CardHeader className="pb-3">
        <CardTitle className="text-lg">Import Gear</CardTitle>
        <CardDescription className="text-sm">
          Import your gear from LighterPack by URL or CSV file
        </CardDescription>
      </CardHeader>
      <CardContent>
        <Tabs defaultValue="url" value={activeTab} onValueChange={(value) => setActiveTab(value as 'csv' | 'url')}>
          <TabsList className="grid w-full grid-cols-2">
            <TabsTrigger value="url" className="flex items-center gap-2">
              <Link className="h-4 w-4" />
              LighterPack URL
            </TabsTrigger>
            <TabsTrigger value="csv" className="flex items-center gap-2">
              <Upload className="h-4 w-4" />
              CSV File
            </TabsTrigger>
          </TabsList>

          <TabsContent value="url" className="mt-4">
            <UrlImport 
              onImportData={handleImportData}
              onListImportData={handleListImportData}
            />
          </TabsContent>

          <TabsContent value="csv" className="mt-4">
            <CsvImport 
              onImportData={handleImportData}
              onListImportData={handleListImportData}
            />
          </TabsContent>
        </Tabs>

        <div className="flex justify-end gap-2 mt-4 pt-3 border-t">
          <Button variant="ghost" onClick={handleClose} size="sm">
            Cancel
          </Button>
        </div>
      </CardContent>
    </Card>
  )
}

