import { decode as decodeHtmlEntities } from 'he'
import { 
  type ParsedGearItem, 
  type GearParseResult,
  type ListParseResult,
  type ParsedList,
  type ParsedListCategory,
  type ParsedListedGearItem, 
  validateParsedGearItem,
  validateParsedList,
  validateParsedListCategory,
  validateParsedListedGearItem
} from './index'

export function parseLighterPackHtml(html: string): GearParseResult {
  const result: GearParseResult = {
    success: false,
    data: [],
    errors: [],
    warnings: [],
    metadata: {}
  }

  try {
    // Extract list name from title or h1
    const titleMatch = html.match(/<title[^>]*>([^<]+)<\/title>/i) || 
                      html.match(/<h1[^>]*>([^<]+)<\/h1>/i)

    if (titleMatch) {
      result.metadata.listName = titleMatch[1].replace(/\s*-\s*LighterPack.*$/i, '').trim()
    }

    // Look for all lpItem elements across all categories
    const itemMatches = html.match(/<li[^>]*class="[^"]*lpItem[^"]*"[^>]*>.*?<\/li>/gis)


    if (!itemMatches || itemMatches.length === 0) {
      result.errors.push('No gear items found in the LighterPack page')
      return result
    }

    // Parse each item
    for (const itemHtml of itemMatches) {
      try {
        const item = parseHtmlItem(itemHtml)
        if (item) {
          const validationErrors = validateParsedGearItem(item)
          if (validationErrors.length === 0) {
            result.data.push(item)
          } else {
            result.errors.push(`Invalid item: ${validationErrors.join(', ')}`)
          }
        }
      } catch (error) {
        const message = error instanceof Error ? error.message : 'Unknown error'
        result.warnings.push(`Failed to parse item: ${message}`)
      }
    }

    // Calculate metadata
    if (result.data.length > 0) {
      result.metadata.totalWeight = result.data.reduce((sum, item) => sum + item.weight_g, 0)
      result.metadata.itemCount = result.data.length
    }

    result.success = result.data.length > 0

    if (result.data.length === 0) {
      result.errors.push('No gear items found in the LighterPack page')
    }

    return result

  } catch (error) {
    result.errors.push(error instanceof Error ? error.message : 'Unknown parsing error')
    return result
  }
}

function parseHtmlItem(itemHtml: string): ParsedGearItem | null {
  try {
    // Extract name (item_type) from lpName span - handle both plain text and anchor tags
    const nameSpanMatch = itemHtml.match(/<span[^>]*class="[^"]*lpName[^"]*"[^>]*>(.*?)<\/span>/is)
    let name = null
    if (nameSpanMatch) {
      // Check if there's an anchor tag inside
      const anchorMatch = nameSpanMatch[1].match(/<a[^>]*>([^<]+)<\/a>/i)
      name = anchorMatch ? anchorMatch[1].trim() : nameSpanMatch[1].trim()
    }

    if (!name) {
      return null
    }

    // Extract description from lpDesc span, or anchor text within lpName
    let description = name // fallback to name

    // Try to get description from lpDescription
    const descMatch = itemHtml.match(/<span[^>]*class="[^"]*lpDescription[^"]*"[^>]*>([^<]+)<\/span>/i)
    if (descMatch?.[1]?.trim()) {
      description = descMatch[1].trim()
    } else {
      // Try to get from anchor text in lpName
      const anchorMatch = itemHtml.match(/<a[^>]*>([^<]+)<\/a>/i)
      if (anchorMatch?.[1]?.trim() && anchorMatch[1].trim() !== name) {
        description = anchorMatch[1].trim()
      }
    }

    // Extract URL from anchor in lpName
    const urlMatch = itemHtml.match(/<a[^>]*href="([^"]+)"/i)
    const url = urlMatch?.[1] ? decodeHtmlEntities(urlMatch[1]) : null

    // Extract weight and unit from lpWeight span and lpUnitSelect
    const weightMatch = itemHtml.match(/<span[^>]*class="[^"]*lpWeight[^"]*"[^>]*>([^<]+)<\/span>/i)
    if (!weightMatch) return null

    const unitMatch = itemHtml.match(/<span[^>]*class="[^"]*lpDisplay[^"]*"[^>]*>([^<]+)<\/span>/i)
    const unit = unitMatch?.[1]?.trim() || 'g'

    const weight = parseFloat(weightMatch[1])
    if (isNaN(weight)) return null

    // Convert to grams based on unit
    let weight_g: number
    switch (unit.toLowerCase()) {
      case 'oz':
        weight_g = Math.round(weight * 28.3495)
        break
      case 'lb':
        weight_g = Math.round(weight * 453.592)
        break
      case 'kg':
        weight_g = Math.round(weight * 1000)
        break
      case 'g':
      default:
        weight_g = Math.round(weight)
        break
    }

    const weight_unit_display = unit as 'g' | 'oz' | 'lb' | 'kg'


    // Check if item is consumable (must have an i element with both lpConsumable and lpActive classes)
    const consumable = /<i[^>]*class="[^"]*lpConsumable[^"]*lpActive[^"]*"[^>]*>|<i[^>]*class="[^"]*lpActive[^"]*lpConsumable[^"]*"[^>]*>/i.test(itemHtml)

    // Extract price from lpPriceCell span
    const priceMatch = itemHtml.match(/<span[^>]*class="[^"]*lpPriceCell[^"]*"[^>]*>\$?([0-9.,]+)<\/span>/i)
    const price = priceMatch ? parseFloat(priceMatch[1].replace(/[,$]/g, '')) : null

    // Use name directly as item_type (preserve original data)
    const item_type = name

    const result = {
      description: description || name, // Use description as the main field, fallback to name
      brand: null, // LighterPack doesn't separate brand info
      model: null,
      weight_g,
      weight_unit_display,
      item_type,
      consumable,
      price,
      notes: null, // LighterPack doesn't have separate notes
      image_url: null,
      url
    }

    return result

  } catch (error) {
    console.warn('Error parsing LighterPack item:', error)
    return null
  }
}

// Parse LighterPack HTML into complete list structure with categories
export function parseLighterPackHtmlToList(html: string, listName?: string): ListParseResult {
  const result: ListParseResult = {
    success: false,
    list: { name: '' },
    categories: [],
    listedGearItems: [],
    errors: [],
    warnings: [],
    metadata: {}
  }

  try {
    // Extract list name from title or h1, or use provided name
    const titleMatch = html.match(/<title[^>]*>([^<]+)<\/title>/i) || 
                      html.match(/<h1[^>]*>([^<]+)<\/h1>/i)

    const extractedListName = titleMatch?.[1]?.replace(/\s*-\s*LighterPack.*$/i, '').trim()
    result.list.name = listName || extractedListName || 'Imported List'

    // Look for category sections (li.lpCategory elements)
    const categoryMatches = html.match(/<li[^>]*class="[^"]*lpCategory[^"]*"[^>]*>.*?<\/li>/gis)

    if (!categoryMatches || categoryMatches.length === 0) {
      result.errors.push('No categories found in the LighterPack page')
      return result
    }

    let sortIndex = 0

    // Parse each category
    for (const categoryHtml of categoryMatches) {
      try {
        const categoryData = parseCategorySection(categoryHtml, sortIndex++)
        if (categoryData) {
          // Validate category
          const categoryErrors = validateParsedListCategory(categoryData.category)
          if (categoryErrors.length > 0) {
            result.errors.push(`Category "${categoryData.category.name}": ${categoryErrors.join(', ')}`)
            continue
          }

          result.categories.push(categoryData.category)

          // Validate and add all gear items in this category
          for (const listedItem of categoryData.listedGearItems) {
            const validationErrors = validateParsedListedGearItem(listedItem)
            if (validationErrors.length > 0) {
              result.warnings.push(`Item in "${categoryData.category.name}": ${validationErrors.join(', ')}`)
              continue
            }

            result.listedGearItems.push(listedItem)
          }
        }
      } catch (error) {
        const message = error instanceof Error ? error.message : 'Unknown error'
        result.warnings.push(`Failed to parse category: ${message}`)
      }
    }

    // Calculate metadata
    if (result.listedGearItems.length > 0) {
      result.metadata.totalWeight = result.listedGearItems.reduce(
        (sum, item) => sum + (item.weight_g_override || item.gearItem.weight_g) * item.quantity, 
        0
      )
      result.metadata.itemCount = result.listedGearItems.length
      result.metadata.categoryCount = result.categories.length
    }

    // Validate the list
    const listErrors = validateParsedList(result.list)
    if (listErrors.length > 0) {
      result.errors.push(...listErrors.map(err => `List: ${err}`))
    }

    result.success = result.errors.length === 0 && result.listedGearItems.length > 0

    if (result.listedGearItems.length === 0) {
      result.errors.push('No gear items found in any categories')
    }

    return result

  } catch (error) {
    result.errors.push(error instanceof Error ? error.message : 'Unknown parsing error')
    return result
  }
}

function parseCategorySection(categoryHtml: string, sortIndex: number): { category: ParsedListCategory, listedGearItems: ParsedListedGearItem[] } | null {
  try {
    // Extract category name from h2.lpCategoryName
    const categoryNameMatch = categoryHtml.match(/<h2[^>]*class="[^"]*lpCategoryName[^"]*"[^>]*>([^<]+)<\/h2>/i)
    if (!categoryNameMatch) {
      return null
    }

    const categoryName = decodeHtmlEntities(categoryNameMatch[1].trim())

    const category: ParsedListCategory = {
      name: categoryName,
      sort_index: sortIndex,
      icon: null,
      color: null
    }

    // Find all lpItem elements within this category
    const itemMatches = categoryHtml.match(/<li[^>]*class="[^"]*lpItem[^"]*"[^>]*>.*?<\/li>/gis) || []

    const listedGearItems: ParsedListedGearItem[] = []
    let itemSortIndex = 0

    for (const itemHtml of itemMatches) {
      try {
        const gearItem = parseHtmlItem(itemHtml)
        if (gearItem) {
          // Parse quantity (default to 1)
          const quantityMatch = itemHtml.match(/<span[^>]*class="[^"]*lpQty[^"]*"[^>]*>([^<]+)<\/span>/i)
          const quantity = quantityMatch ? parseInt(quantityMatch[1], 10) : 1

          // Check if worn (look for lpWorn class)
          const worn = /<[^>]*class="[^"]*lpWorn[^"]*"[^>]*>/.test(itemHtml)

          const listedGearItem: ParsedListedGearItem = {
            gearItem,
            categoryName,
            quantity: isNaN(quantity) || quantity <= 0 ? 1 : quantity,
            worn,
            weight_g_override: null,
            notes: null,
            sort_index: itemSortIndex++
          }

          listedGearItems.push(listedGearItem)
        }
      } catch (error) {
        // Skip individual items that fail to parse
        continue
      }
    }

    return { category, listedGearItems }

  } catch (error) {
    return null
  }
}

export async function parseLighterPackUrl(url: string): Promise<GearParseResult> {
  const result: GearParseResult = {
    success: false,
    data: [],
    errors: [],
    warnings: []
  }

  // Validate URL format
  if (!url.match(/^https:\/\/lighterpack\.com\/r\/[a-zA-Z0-9]+$/)) {
    result.errors.push('Invalid LighterPack URL format. Expected: https://lighterpack.com/r/[ID]')
    return result
  }

  // For now, direct URL import is not implemented
  result.errors.push('Direct URL import not yet implemented. Please use CSV export from LighterPack for now.')
  return result
}

