function parseCategorySection(categoryHtml: string, sortIndex: number): { category: ParsedListCategory, listedGearItems: ParsedListedGearItem[] } | null {
  try {
    // Extract category name from h2.lpCategoryName within li.lpHeader
    // The structure is: li.lpCategory > ul.lpItems > li.lpHeader > h2.lpCategoryName
    const headerMatch = categoryHtml.match(/<h2[^>]*class="[^"]*lpCategoryName[^"]*"[^>]*>([^<]+)<\/h2>/i)
    if (!headerMatch) {
      return null
    }

    const categoryName = decodeHtmlEntities(headerMatch[1].trim())

    const category: ParsedListCategory = {
      name: categoryName,
      sort_index: sortIndex,
      icon: null,
      color: null
    }

    // Find all lpItem elements within this category, but exclude lpHeader
    const itemsSection = categoryHtml.match(/<ul[^>]*class="[^"]*lpItems[^"]*">[\s\S]*<\/ul>/i)
    if (!itemsSection) {
      return { category, listedGearItems: [] }
    }

    // Find individual items within the items section, excluding header
    const itemMatches = itemsSection[0].match(/<li[^>]*class="[^"]*lpItem[^"]*"[^>]*(?:(?!lpHeader).)*>[\s\S]*?<\/li>/g) || []

    const listedGearItems: ParsedListedGearItem[] = []
    let itemSortIndex = 0

    for (const itemHtml of itemMatches) {
      try {
        // Double check - skip if this contains lpHeader
        if (itemHtml.includes('lpHeader') || itemHtml.includes('lpItemsHeader')) {
          continue
        }

        const gearItem = parseHtmlItem(itemHtml)
        if (gearItem) {
          // Parse quantity from lpQtyCell or qty attribute
          let quantity = 1
          const qtyMatch = itemHtml.match(/<span[^>]*class="[^"]*lpQtyCell[^"]*"[^>]*(?:[^>]*qty(\d+)[^>]*)?[^>]*>[\s]*(\d+)[\s]*<\/span>/i)
          if (qtyMatch) {
            quantity = parseInt(qtyMatch[2] || qtyMatch[1], 10) || 1
          }

          // Check if worn - look for lpWorn with lpActive classes together
          const worn = /<i[^>]*class="[^"]*lpWorn[^"]*lpActive[^"]*"/.test(itemHtml) || /<i[^>]*class="[^"]*lpActive[^"]*lpWorn[^"]*"/.test(itemHtml)

          const listedGearItem: ParsedListedGearItem = {
            gearItem,
