  })

  // Fetch existing gear items on mount
  useEffect(() => {
    const fetchExistingItems = async () => {
      if (!user) return

      try {
        const gearRepository = createGearRepository(user.id)
        const items = await gearRepository.list()
        setExistingItems(items)
      } catch (error) {
        console.error('Failed to fetch existing gear items:', error)
      }
    }

    fetchExistingItems()
  }, [user])

  // Function to check if two items are duplicates
  const isDuplicate = (importItem: ParsedGearItem, existingItem: GearItem): boolean => {
    // Match on item_type and description (case insensitive)
    const importItemType = importItem.item_type.toLowerCase().trim()
    const importDescription = (importItem.description || '').toLowerCase().trim()
    const existingItemType = existingItem.item_type.toLowerCase().trim()
    const existingDescription = (existingItem.description || '').toLowerCase().trim()

    return importItemType === existingItemType && importDescription === existingDescription
  }

  const handleImportData = (data: ParsedGearItem[], errors: string[] = [], warnings: string[] = [], metadata?: any) => {
    // Deduplicate against existing items
    const newItems: ParsedGearItem[] = []
    const duplicates: ParsedGearItem[] = []

    data.forEach(importItem => {
      const isDuplicateItem = existingItems.some(existing => isDuplicate(importItem, existing))
      if (isDuplicateItem) {
        duplicates.push(importItem)
      } else {
        newItems.push(importItem)
      }
    })

    // Add deduplication warnings (summary only, no ugly lists)
    const updatedWarnings = [...warnings]
    if (duplicates.length > 0) {
      updatedWarnings.push(
        `${duplicates.length} items skipped as duplicates (already exist in your gear library)`
      )
    }

    if (newItems.length > 0) {
      updatedWarnings.push(`${newItems.length} new items ready to import`)
    }

    setImportState({
      step: 'preview', // Always show preview, even if no new items
      mode: 'gear',
      items: data,
      newItems,
      duplicates,
      errors,
      warnings: updatedWarnings,
      metadata,
      listResult: undefined
    })
  }

  // New handler for list imports
  const handleListImportData = (listResult: ListParseResult) => {
    // For list imports, we don't do gear-level duplicate checking
    // The import service will handle reusing existing gear items
    // but we still create the complete list structure

    setImportState({
      step: 'preview',
      mode: 'list',
      items: [], // Not used in list mode
      newItems: [], // Not used in list mode - all items are shown in the list
      duplicates: [], // Not used in list mode - duplicates are handled at import time
      errors: listResult.errors,
      warnings: listResult.warnings,
      metadata: listResult.metadata,
      listResult
    })
  }


  const handleReset = () => {
    setImportState({
      step: 'input',
      mode: 'gear',
      items: [],
      newItems: [],
      duplicates: [],
      errors: [],
      warnings: [],
      metadata: undefined,
      listResult: undefined
    })
  }

  const handleClose = () => {
    handleReset()
    onCancel?.()
  }

  if (importState.step === 'preview') {
    return (
      <ImportPreview
        mode={importState.mode}
        newItems={importState.newItems}
        duplicates={importState.duplicates}
        errors={importState.errors}
        warnings={importState.warnings}
        metadata={importState.metadata}
        listResult={importState.listResult}
        onCancel={handleReset}
        className={className}
      />
    )
  }


  return (
    <Card className={className}>
      <CardHeader className="pb-3">
        <CardTitle className="text-lg">Import from LighterPack</CardTitle>
        <CardDescription className="text-sm">
          Import your complete pack list with categories and organization
        </CardDescription>
      </CardHeader>
      <CardContent>
        <Tabs defaultValue="url" value={activeTab} onValueChange={(value) => setActiveTab(value as 'csv' | 'url')}>
          <TabsList className="grid w-full grid-cols-2">
            <TabsTrigger value="url" className="flex items-center gap-2">
              <Link className="h-4 w-4" />
              LighterPack URL
            </TabsTrigger>
            <TabsTrigger value="csv" className="flex items-center gap-2">
              <Upload className="h-4 w-4" />
              CSV File
            </TabsTrigger>
          </TabsList>

          <TabsContent value="url" className="mt-4">
            <UrlImport 
              onImportData={handleImportData}
              onListImportData={handleListImportData}
            />
          </TabsContent>

          <TabsContent value="csv" className="mt-4">
            <CsvImport 
              onImportData={handleImportData}
              onListImportData={handleListImportData}
            />
          </TabsContent>
        </Tabs>

        <div className="flex justify-end gap-2 mt-4 pt-3 border-t">
          <Button variant="ghost" onClick={handleClose} size="sm">
            Cancel
          </Button>
        </div>
      </CardContent>
    </Card>
  )
}

import { useState } from 'react'
import { useNavigate } from 'react-router-dom'
import { useAuth } from '@/contexts/AuthContext'
import { createGearRepository } from '@/lib/gearRepository'
import { createImportService } from '@/lib/importService'
import { Button } from '@/components/ui/button'
import { Alert, AlertDescription } from '@/components/ui/alert'
import { CheckCircle, AlertCircle, Package, Weight, Loader2, List } from 'lucide-react'
import { StatTile } from '@/components/ui/stat-tile'
import { formatWeightForDisplay } from '@/utils/weight'
import type { ParsedGearItem, ListParseResult } from '@/utils/parser'

interface ImportPreviewProps {
  mode: 'gear' | 'list'
  newItems: ParsedGearItem[]
  duplicates: ParsedGearItem[]
  errors?: string[]
  warnings?: string[]
  metadata?: any
  listResult?: ListParseResult
  onCancel: () => void
  className?: string
}

export function ImportPreview({
  mode,
  newItems,
  duplicates,
  errors = [],
  metadata,
  listResult,
  onCancel,
  className
}: ImportPreviewProps) {
  const { user } = useAuth()
  const navigate = useNavigate()
  const [isImporting, setIsImporting] = useState(false)
  const [importError, setImportError] = useState<string | null>(null)

  // Calculate stats based on mode
  const stats = mode === 'list' && listResult ? {
    totalWeight: listResult.metadata?.totalWeight || 0,
    itemCount: listResult.metadata?.itemCount || 0,
    categoryCount: listResult.metadata?.categoryCount || 0,
    hasItems: listResult.listedGearItems.length > 0
  } : {
    totalWeight: newItems.reduce((sum, item) => sum + item.weight_g, 0),
    itemCount: newItems.length,
    categoryCount: new Set(newItems.map(item => item.item_type)).size,
    hasItems: newItems.length > 0
  }

  const handleImport = async () => {
    if (!user) {
      setImportError('User not authenticated')
      return
    }

    setIsImporting(true)
    setImportError(null)

    try {
      if (mode === 'list' && listResult) {
        // Import complete list structure
        const importService = createImportService(user.id)
        const result = await importService.importList(listResult)

        if (!result.success) {
          setImportError(result.errors.join(', '))
          return
        }

        // Navigate to the new list (if we have list pages implemented)
        navigate('/lists') // For now, go to lists page
      } else {
        // Legacy gear-only import
        const gearRepository = createGearRepository(user.id)

        // Convert newItems to the format expected by the repository
        const itemsToCreate = newItems.map(item => ({
          item_type: item.item_type,
          description: item.description,
          brand: item.brand,
          model: item.model,
          consumable: item.consumable,
          price: item.price,
          weight_g: item.weight_g,
          weight_unit_display: item.weight_unit_display,
          notes: item.notes,
          image_url: item.image_url,
          url: item.url
        }))

        // Use createMany for bulk insert
        await gearRepository.createMany(itemsToCreate)

        // Redirect to gear closet
        navigate('/gear')
      }
    } catch (error) {
      console.error('Failed to import:', error)
      setImportError(error instanceof Error ? error.message : 'Unknown error occurred')
    } finally {
      setIsImporting(false)
    }
  }


  return (
    <div className={className}>
      <div className="pb-4">
        <div className="flex items-center gap-2 text-lg font-semibold mb-1">
          <CheckCircle className="h-4 w-4 text-green-600" />
          List Import Preview
          {(metadata?.listName || listResult?.list.name) && (
            <span className="text-sm font-normal text-muted-foreground">
              • {metadata?.listName || listResult?.list.name}
            </span>
          )}
        </div>
        <div className="text-sm text-muted-foreground">
          {mode === 'list' ? (
            `${stats.itemCount} items in ${stats.categoryCount} categories ready to import as a list`
          ) : stats.hasItems ? (
            <>
              {newItems.length} new items ready to import
              {duplicates.length > 0 && (
                <span className="text-muted-foreground"> • {duplicates.length} duplicates skipped</span>
              )}
            </>
          ) : (
            "No new items to import (all items already exist)"
          )}
        </div>
      </div>

      <div className="space-y-4">
        {/* Errors */}
        {errors.length > 0 && (
          <Alert variant="destructive">
            <AlertCircle className="h-4 w-4" />
            <AlertDescription>
              <div className="font-medium mb-2">Import Errors:</div>
              <ul className="list-disc list-inside space-y-1">
                {errors.map((error, i) => (
                  <li key={i} className="text-sm">{error}</li>
                ))}
              </ul>
            </AlertDescription>
          </Alert>
        )}

        {/* Summary Stats - Compact */}
        <div className="grid grid-cols-3 gap-3">
          <StatTile
            title="Items"
            value={mode === 'list' ? stats.itemCount : newItems.length}
            description="total items"
            icon={Package}
            iconColor="success"
            compact={true}
          />
          <StatTile
            title="Total Weight"
            value={formatWeightForDisplay(stats.totalWeight)}
            description="total weight"
            icon={Weight}
            iconColor="info"
            compact={true}
          />
          <StatTile
            title="Categories"
            value={stats.categoryCount}
            description="categories"
            icon={List}
            iconColor="primary"
            compact={true}
          />
        </div>

        {/* Import Error */}
        {importError && (
          <Alert variant="destructive">
            <AlertCircle className="h-4 w-4" />
            <AlertDescription>
              <div className="font-medium mb-2">Import Failed:</div>
              <div className="text-sm">{importError}</div>
            </AlertDescription>
          </Alert>
        )}

        {/* Actions */}
        <div className="flex justify-center gap-2 pt-2">
          {stats.hasItems ? (
            <>
              <Button onClick={handleImport} disabled={isImporting}>
                {isImporting ? (
                  <>
                    <Loader2 className="h-3 w-3 mr-1 animate-spin" />
                    Importing...
                  </>
                ) : (
                  `Import List (${stats.itemCount} items)`
                )}
              </Button>
              <Button variant="outline" onClick={onCancel} disabled={isImporting}>
                Back
              </Button>
            </>
          ) : (
            <Button variant="outline" onClick={onCancel}>
              Back to Import
            </Button>
          )}
        </div>
      </div>
    </div>
  )
}

