const itemsContent = itemsSection[0]
const itemMatches: string[] = []

// Split by lpItem class to find individual items
const itemParts = itemsContent.split(/<li[^>]*class="[^"]*lpItem[^"]*"[^>]*>/)

for (let i = 1; i < itemParts.length; i++) {
  // Find the closing </li> for this item
  let depth = 0
  let endIndex = -1

  for (let j = 0; j < itemParts[i].length; j++) {
    const remaining = itemParts[i].substring(j)
    if (remaining.startsWith('<li')) {
      depth++
    } else if (remaining.startsWith('</li>')) {
      if (depth === 0) {
        endIndex = j
        break
      } else {
        depth--
      }
    }
  }

  if (endIndex !== -1) {
    const itemContent = itemParts[i].substring(0, endIndex)
    const fullItemHtml = `<li class="lpItem">${itemContent}</li>`
    itemMatches.push(fullItemHtml)
  }
}

